-- UK bank holidays: load data (postgres)
-- Generated by uk_bank_holidays for 1871 to 2035 (1746 rows).
-- Safe to re-run: rows are staged and upserted on ("holiday_date", "rule_id"), so missing rows are
-- added, changed rows are updated and nothing is duplicated.
-- Rows that are not in this script are never deleted (generate with --prune to change that).

DROP TABLE IF EXISTS pg_temp."bank_holidays_stage";
CREATE TEMPORARY TABLE "bank_holidays_stage" (LIKE "bank_holidays");


SELECT "holiday_date", "rule_id", "holiday_key", "holiday_name", "holiday_type", "england_and_wales", "scotland", "northern_ireland", "is_substitute", "notes", "source_ids" FROM pg_temp."bank_holidays_stage"
ON CONFLICT ("holiday_date", "rule_id") DO UPDATE SET
    "holiday_key" = EXCLUDED."holiday_key",
    "holiday_name" = EXCLUDED."holiday_name",
    "holiday_type" = EXCLUDED."holiday_type",
    "england_and_wales" = EXCLUDED."england_and_wales",
    "scotland" = EXCLUDED."scotland",
    "northern_ireland" = EXCLUDED."northern_ireland",
    "is_substitute" = EXCLUDED."is_substitute",
    "notes" = EXCLUDED."notes",
    "source_ids" = EXCLUDED."source_ids";

DROP TABLE pg_temp."bank_holidays_stage";
